import numpy as np

def slerp(q0, q1, ts):
    """q0, q1: (4,) quaternions (w, x, y, z). ts: (T,). Return (T, 4)."""
    q0, q1, ts = np.asarray(q0, float), np.asarray(q1, float), np.asarray(ts, float)
    out = (1 - ts)[:, None] * q0 + ts[:, None] * q1
    return out / np.linalg.norm(out, axis=1, keepdims=True)
